#include <bits/stdc++.h>
using namespace std;

constexpr long long MOD = 1'000'000'007LL;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<int> a(n);
    int limit = 2;
    for (int &x : a) {
        cin >> x;
        limit = max(limit, x);
    }
    reverse(a.begin(), a.end());

    vector<int> primeFactor(limit + 1);
    for (int i = 2; i <= limit; ++i) {
        if (primeFactor[i] == 0) {
            for (int j = i; j <= limit; j += i) {
                primeFactor[j] = i;
            }
        }
    }

    vector<int> have(limit + 1);
    vector<unsigned char> taken(limit + 1);

    int z = 0;

    for (int value : a) {
        bool ok = false;

        if (!taken[value]) {
            taken[value] = true;
            if (have[value] < 1) ok = true;
            have[value] = max(have[value], 1);
        } else {
            int y = value - 1;

            while (y > 1) {
                int prime = primeFactor[y];
                int exponent = 0;

                while (y % prime == 0) {
                    y /= prime;
                    ++exponent;
                }

                taken[prime] = true;
                if (have[prime] < exponent) ok = true;
                have[prime] = max(have[prime], exponent);
            }
        }

        if (!ok) z = 1;
    }

    long long result = 1;
    for (int i = 2; i <= limit; ++i) {
        for (int j = 0; j < have[i]; ++j) {
            result = result * i % MOD;
        }
    }

    cout << (result + z) % MOD;
    return 0;
}

